// План specs/admin-plans.md, 1.8 (кейс AP-06). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab } from './plans-helpers';
import { accountRows, loadedRowCount, filterControl, filterOptions, selectFilter, expectColumnEqualsOrEmpty, FILTER } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Subscription status filter keeps only rows with the selected status, for every option #ca557707 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(180_000);
    await setLanguage(page, 'en');
    await openPlansTab(page);
    const total = await loadedRowCount(page);

    const control = filterControl(page, FILTER.statuses);
    const options = await filterOptions(page, control, 'All statuses');
    expect(options.length).toBeGreaterThan(0);
    // Комментарий программиста 30.9: 6 статусов — Active, Trial, Trial ended, Payment issue, Canceled, Free.
    expect(options, 'значения фильтра статуса').toHaveLength(6);
    for (const option of options) {
      await test.step(option, async () => {
        await selectFilter(page, control, option);
        await expectColumnEqualsOrEmpty(page, 'Subscription status', option);
      });
    }

    await selectFilter(page, control, 'All statuses');
    await expect(accountRows(page)).toHaveCount(total);
  });
});
